import{_ as l,a0 as d,w as h,s as o,ao as n,I as p,x as e,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"通過實例學習 tcpdump 命令 | LCTT x X-CMD","titleTemplate":false,"description":"通過實例學習 tcpdump 命令 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通過實例學習 tcpdump 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通過實例學習 tcpdump 命令 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171109 Learn how to use tcpdump command with examples","title":"通過實例學習 tcpdump 命令","tag":"201801","desc":""},"relativePath":"201801/20171109 Learn how to use tcpdump command with examples.md","filePath":"[post].md"}'),r={name:"201801/20171109 Learn how to use tcpdump command with examples.md"};function c(u,a,g,k,b,m){const s=d("Link");return h(),o("div",null,[a[15]||(a[15]=n('<h1 id="通過實例學習-tcpdump-命令" tabindex="-1">通過實例學習 tcpdump 命令 <a class="header-anchor" href="#通過實例學習-tcpdump-命令" aria-label="Permalink to “通過實例學習 tcpdump 命令”">​</a></h1><p><code>tcpdump</code> 是一個很常用的網絡包分析工具，可以用來顯示通過網絡傳輸到本系統的 TCP/IP 以及其他網絡的數據包。<code>tcpdump</code> 使用 libpcap 庫來抓取網絡報，這個庫在幾乎在所有的 Linux/Unix 中都有。</p><p><code>tcpdump</code> 可以從網卡或之前創建的數據包文件中讀取內容，也可以將包寫入文件中以供後續使用。必須是 root 用户或者使用 sudo 特權來運行 <code>tcpdump</code>。</p><p>在本文中，我們將會通過一些實例來演示如何使用 <code>tcpdump</code> 命令，但首先讓我們來看看在各種 Linux 操作系統中是如何安裝 <code>tcpdump</code> 的。</p>',4)),p("ul",null,[p("li",null,[a[1]||(a[1]=e("推薦閲讀：",-1)),i(s,{href:"http://linuxtechlab.com/monitoring-network-bandwidth-iftop-command/"},{default:t(()=>[...a[0]||(a[0]=[e("使用 iftop 命令監控網絡帶寬 ",-1)])]),_:1})])]),a[16]||(a[16]=n(`<h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p><code>tcpdump</code> 默認在幾乎所有的 Linux 發行版中都可用，但若你的 Linux 上沒有的話，使用下面方法進行安裝。</p><h4 id="centos-rhel" tabindex="-1">CentOS/RHEL <a class="header-anchor" href="#centos-rhel" aria-label="Permalink to “CentOS/RHEL”">​</a></h4><p>使用下面命令在 CentOS 和 RHEL 上安裝 <code>tcpdump</code>，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install tcpdump*</span></span></code></pre></div><h4 id="fedora" tabindex="-1">Fedora <a class="header-anchor" href="#fedora" aria-label="Permalink to “Fedora”">​</a></h4><p>使用下面命令在 Fedora 上安裝 <code>tcpdump</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf install tcpdump</span></span></code></pre></div><h4 id="ubuntu-debian-linux-mint" tabindex="-1">Ubuntu/Debian/Linux Mint <a class="header-anchor" href="#ubuntu-debian-linux-mint" aria-label="Permalink to “Ubuntu/Debian/Linux Mint”">​</a></h4><p>在 Ubuntu/Debain/Linux Mint 上使用下面命令安裝 <code>tcpdump</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ apt-get install tcpdump</span></span></code></pre></div><p>安裝好 <code>tcpdump</code> 後，現在來看一些例子。</p><h3 id="案例演示" tabindex="-1">案例演示 <a class="header-anchor" href="#案例演示" aria-label="Permalink to “案例演示”">​</a></h3><h4 id="從所有網卡中捕獲數據包" tabindex="-1">從所有網卡中捕獲數據包 <a class="header-anchor" href="#從所有網卡中捕獲數據包" aria-label="Permalink to “從所有網卡中捕獲數據包”">​</a></h4><p>運行下面命令來從所有網卡中捕獲數據包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump -i any</span></span></code></pre></div><h4 id="從指定網卡中捕獲數據包" tabindex="-1">從指定網卡中捕獲數據包 <a class="header-anchor" href="#從指定網卡中捕獲數據包" aria-label="Permalink to “從指定網卡中捕獲數據包”">​</a></h4><p>要從指定網卡中捕獲數據包，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump -i eth0</span></span></code></pre></div><h4 id="將捕獲的包寫入文件" tabindex="-1">將捕獲的包寫入文件 <a class="header-anchor" href="#將捕獲的包寫入文件" aria-label="Permalink to “將捕獲的包寫入文件”">​</a></h4><p>使用 <code>-w</code> 選項將所有捕獲的包寫入文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump -i eth1 -w packets_file</span></span></code></pre></div><h4 id="讀取之前產生的-tcpdump-文件" tabindex="-1">讀取之前產生的 tcpdump 文件 <a class="header-anchor" href="#讀取之前產生的-tcpdump-文件" aria-label="Permalink to “讀取之前產生的 tcpdump 文件”">​</a></h4><p>使用下面命令從之前創建的 tcpdump 文件中讀取內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump -r packets_file</span></span></code></pre></div><h4 id="獲取更多的包信息-並且以可讀的形式顯示時間戳" tabindex="-1">獲取更多的包信息，並且以可讀的形式顯示時間戳 <a class="header-anchor" href="#獲取更多的包信息-並且以可讀的形式顯示時間戳" aria-label="Permalink to “獲取更多的包信息，並且以可讀的形式顯示時間戳”">​</a></h4><p>要獲取更多的包信息同時以可讀的形式顯示時間戳，使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump -ttttnnvvS</span></span></code></pre></div><h4 id="查看整個網絡的數據包" tabindex="-1">查看整個網絡的數據包 <a class="header-anchor" href="#查看整個網絡的數據包" aria-label="Permalink to “查看整個網絡的數據包”">​</a></h4><p>要獲取整個網絡的數據包，在終端執行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump net 192.168.1.0/24</span></span></code></pre></div><h4 id="根據-ip-地址查看報文" tabindex="-1">根據 IP 地址查看報文 <a class="header-anchor" href="#根據-ip-地址查看報文" aria-label="Permalink to “根據 IP 地址查看報文”">​</a></h4><p>要獲取指定 IP 的數據包，不管是作為源地址還是目的地址，使用下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump host 192.168.1.100</span></span></code></pre></div><p>要指定 IP 地址是源地址或是目的地址則使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump src 192.168.1.100</span></span>
<span class="line"><span>$ tcpdump dst 192.168.1.100</span></span></code></pre></div><h4 id="查看某個協議或端口號的數據包" tabindex="-1">查看某個協議或端口號的數據包 <a class="header-anchor" href="#查看某個協議或端口號的數據包" aria-label="Permalink to “查看某個協議或端口號的數據包”">​</a></h4><p>要查看某個協議的數據包，運行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump ssh</span></span></code></pre></div><p>要捕獲某個端口或一個範圍的數據包，使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump port 22</span></span>
<span class="line"><span>$ tcpdump portrange 22-125</span></span></code></pre></div><p>我們也可以與 <code>src</code> 和 <code>dst</code> 選項連用來捕獲指定源端口或指定目的端口的報文。</p><p>我們還可以使用“與” （<code>and</code>，<code>&amp;&amp;</code>）、“或” （<code>or</code>，<code>||</code> ) 和“非”（<code>not</code>，<code>!</code>） 來將兩個條件組合起來。當我們需要基於某些條件來分析網絡報文是非常有用。</p><h4 id="使用-與" tabindex="-1">使用“與” <a class="header-anchor" href="#使用-與" aria-label="Permalink to “使用“與””">​</a></h4><p>可以使用 <code>and</code> 或者符號 <code>&amp;&amp;</code> 來將兩個或多個條件組合起來。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump src 192.168.1.100 &amp;&amp; port 22 -w ssh_packets</span></span></code></pre></div><h4 id="使用-或" tabindex="-1">使用“或” <a class="header-anchor" href="#使用-或" aria-label="Permalink to “使用“或””">​</a></h4><p>“或”會檢查是否匹配命令所列條件中的其中一條，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump src 192.168.1.100 or dst 192.168.1.50 &amp;&amp; port 22 -w ssh_packets</span></span>
<span class="line"><span>$ tcpdump port 443 or 80 -w http_packets</span></span></code></pre></div><h4 id="使用-非" tabindex="-1">使用“非” <a class="header-anchor" href="#使用-非" aria-label="Permalink to “使用“非””">​</a></h4><p>當我們想表達不匹配某項條件時可以使用“非”，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump -i eth0 src port not 22</span></span></code></pre></div><p>這會捕獲 eth0 上除了 22 號端口的所有通訊。</p><p>我們的教程至此就結束了，在本教程中我們講解了如何安裝並使用 <code>tcpdump</code> 來捕獲網絡數據包。如有任何疑問或建議，歡迎留言。</p><hr>`,55)),p("p",null,[a[3]||(a[3]=e("via: ",-1)),i(s,{href:"http://linuxtechlab.com/learn-use-tcpdump-command-examples/"},{default:t(()=>[...a[2]||(a[2]=[e("http://linuxtechlab.com/learn-use-tcpdump-command-examples/",-1)])]),_:1})]),p("p",null,[a[7]||(a[7]=e("作者：",-1)),i(s,{href:"http://linuxtechlab.com/author/shsuain/"},{default:t(()=>[...a[4]||(a[4]=[e("Shusain",-1)])]),_:1}),a[8]||(a[8]=e(" 譯者：",-1)),i(s,{href:"https://github.com/lujun9972"},{default:t(()=>[...a[5]||(a[5]=[e("lujun9972",-1)])]),_:1}),a[9]||(a[9]=e(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:t(()=>[...a[6]||(a[6]=[e("wxy",-1)])]),_:1})]),p("p",null,[a[12]||(a[12]=e("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[10]||(a[10]=[e("LCTT",-1)])]),_:1}),a[13]||(a[13]=e(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:t(()=>[...a[11]||(a[11]=[e("Linux中國",-1)])]),_:1}),a[14]||(a[14]=e(" 榮譽推出",-1))])])}const y=l(r,[["render",c]]);export{C as __pageData,y as default};
